# ---------------------------------------------------------------------------
# 1. _convert_d3_exports edge cases
# ---------------------------------------------------------------------------


class TestConvertD3Exports:
    """Edge cases in the regex that converts ESM export{} blocks to var decls."""

    def test_simple_alias(self):
        from ferrum._html import _convert_d3_exports

        source = "export{ri as brush,ni as brushY}"
        result = _convert_d3_exports(source)
        assert "var brush=ri,brushY=ni;" == result

    def test_no_alias(self):
        """Bare identifiers (no 'as') should become var declarations."""
        from ferrum._html import _convert_d3_exports

        result = _convert_d3_exports("export{foo,bar}")
        assert "var foo,bar;" == result

    def test_mixed_alias_and_bare(self):
        from ferrum._html import _convert_d3_exports

        result = _convert_d3_exports("export{a as x,b,c as z}")
        assert "var x=a,b,z=c;" == result

    def test_real_d3_bundle(self):
        """The real d3-interactions.js export block must convert without error."""
        from pathlib import Path

        from ferrum._html import _convert_d3_exports, _WASM_DIR

        d3_src = (_WASM_DIR / "d3-interactions.js").read_text()
        result = _convert_d3_exports(d3_src)
        # Must not contain the original export{...} block
        assert "export{" not in result
        # Must contain the converted var declarations
        assert "var " in result
        # Key D3 symbols must exist as variables
        for sym in ("brush", "zoom", "select", "zoomIdentity", "zoomTransform", "pointer"):
            assert sym in result, f"D3 symbol {sym!r} missing after conversion"

    def test_empty_export_block(self):
        """An empty export{} should become 'var ;' -- degenerate but not crashing."""
        from ferrum._html import _convert_d3_exports

        result = _convert_d3_exports("export{}")
        # Empty braces -> the regex should NOT match (nothing inside braces is
        # matched by [^}]+ which requires at least one char).
        # So the source should pass through unchanged.
        assert result == "export{}"

    def test_spaces_around_alias(self):
        """Spaces around 'as' and identifiers should be handled."""
        from ferrum._html import _convert_d3_exports

        result = _convert_d3_exports("export{ ri as brush , ni as brushY }")
        assert "brush=ri" in result
        assert "brushY=ni" in result

    def test_multiple_export_blocks(self):
        """Multiple export{} blocks in the same source should all convert."""
        from ferrum._html import _convert_d3_exports

        source = "export{a as x};some code;export{b as y}"
        result = _convert_d3_exports(source)
        assert "x=a" in result
        assert "y=b" in result
        assert "export{" not in result


# ---------------------------------------------------------------------------
# 2. _strip_anywidget_for_standalone edge cases
# ---------------------------------------------------------------------------


class TestStripAnywidget:
    """Verify the stripping pipeline against the real JS source and synthetic inputs."""

    def test_real_source_no_residual_exports(self):
        """The real ferrum-anywidget.js must strip cleanly: no leftover exports."""
        from ferrum._html import _strip_anywidget_for_standalone, _WASM_DIR

        source = (_WASM_DIR / "ferrum-anywidget.js").read_text()
        result = _strip_anywidget_for_standalone(source)
        for line in result.splitlines():
            s = line.lstrip()
            assert not s.startswith("export "), f"residual export: {s[:80]!r}"
            assert not s.startswith("export{"), f"residual export: {s[:80]!r}"

    def test_no_b64_bootstrap_block(self):
        """Stripped JS must not contain the _B64 / _raw / _bytes bootstrap."""
        from ferrum._html import _strip_anywidget_for_standalone, _WASM_DIR

        source = (_WASM_DIR / "ferrum-anywidget.js").read_text()
        result = _strip_anywidget_for_standalone(source)
        assert "const _B64" not in result
        assert "const _raw" not in result
        assert "const _bytes" not in result

    def test_no_ensure_wasm_function(self):
        """Stripped JS must not contain the _ensureWasm function definition."""
        from ferrum._html import _strip_anywidget_for_standalone, _WASM_DIR

        source = (_WASM_DIR / "ferrum-anywidget.js").read_text()
        result = _strip_anywidget_for_standalone(source)
        assert "function _ensureWasm" not in result

    def test_ensure_wasm_calls_replaced(self):
        """All _ensureWasm() call sites must be replaced with the comment."""
        from ferrum._html import _strip_anywidget_for_standalone, _WASM_DIR

        source = (_WASM_DIR / "ferrum-anywidget.js").read_text()
        result = _strip_anywidget_for_standalone(source)
        # The original has "await _ensureWasm();" -- that must become a comment
        if "_ensureWasm" in result:
            assert "// WASM already initialized" in result

    def test_no_anywidget_render_function(self):
        """Stripped JS must not contain the anywidget render({ model, el }) function."""
        from ferrum._html import _strip_anywidget_for_standalone, _WASM_DIR

        source = (_WASM_DIR / "ferrum-anywidget.js").read_text()
        result = _strip_anywidget_for_standalone(source)
        assert "model.get" not in result
        assert "model.set" not in result
        assert "model.save_changes" not in result
        assert "model.on(" not in result

    def test_create_standalone_adapter_not_exported(self):
        """createStandaloneAdapter must exist but NOT be exported."""
        from ferrum._html import _strip_anywidget_for_standalone, _WASM_DIR

        source = (_WASM_DIR / "ferrum-anywidget.js").read_text()
        result = _strip_anywidget_for_standalone(source)
        assert "function createStandaloneAdapter" in result
        assert "export function createStandaloneAdapter" not in result

    def test_render_chart_reexport_removed(self):
        """The 'export { _render as renderChart }' export statement must be removed.
        The preceding comment is inert and acceptable."""
        from ferrum._html import _strip_anywidget_for_standalone, _WASM_DIR

        source = (_WASM_DIR / "ferrum-anywidget.js").read_text()
        result = _strip_anywidget_for_standalone(source)
        # The actual export statement must be gone
        assert "export { _render as renderChart }" not in result

    def test_raises_on_unmatched_export(self):
        """If a novel export keyword remains, the guard must raise."""
        from ferrum._html import _strip_anywidget_for_standalone

        bad_js = (
            "export function unexpectedExport() {}\nexport function createStandaloneAdapter() {}\n"
        )
        with pytest.raises(RuntimeError, match="residual export"):
            _strip_anywidget_for_standalone(bad_js)


# ---------------------------------------------------------------------------
# 3. assemble_html: scene JSON escaping and structural checks
# ---------------------------------------------------------------------------


class TestAssembleHtml:
    """Structural checks on the assembled HTML output."""

    def _assemble(self, scene_json, **kwargs):
        from ferrum._html import assemble_html

        return assemble_html(scene_json, **kwargs)

    def test_backtick_in_scene_json_escaped(self):
        """Backticks in scene JSON must be escaped to prevent template literal breakout."""
        scene = json.dumps({"panels": [], "width": 300, "height": 200, "label": "a`b"})
        html = self._assemble(scene)
        # The escaped version inside the JS template literal
        assert "a\\`b" in html
        # Raw backtick should NOT appear unescaped in the SCENE_JSON literal
        # (the template literal itself uses backticks, so an interior one would break)
        scene_start = html.index("const SCENE_JSON = `")
        scene_end = html.index("`;", scene_start)
        scene_literal = html[scene_start:scene_end]
        # No unescaped backtick inside the literal (after the opening one)
        inner = scene_literal[len("const SCENE_JSON = `") :]
        assert "`" not in inner.replace("\\`", "")

    def test_dollar_brace_in_scene_json_escaped(self):
        """${} in scene JSON must be escaped to prevent JS interpolation."""
        scene = json.dumps({"panels": [], "width": 300, "height": 200, "expr": "${alert(1)}"})
        html = self._assemble(scene)
        assert "\\${alert(1)}" in html

    def test_script_close_tag_escaped(self):
        """</script> in scene JSON must be escaped to prevent HTML injection."""
        scene = json.dumps({"panels": [], "width": 300, "height": 200, "xss": "</script>"})
        html = self._assemble(scene)
        # The escaping replaces `</` with `<\/`
        assert "<\\/script>" in html
        # The raw close tag must NOT appear inside the script block
        script_block = html.split('<script type="module">')[1].split("</script>")[0]
        assert "</script>" not in script_block

    def test_backslash_in_scene_json_escaped(self):
        """Backslashes in scene JSON must be double-escaped for the template literal.
        Input 'C:\\Users' -> JSON serializes to 'C:\\\\Users' -> escaping doubles
        each \\ to \\\\ -> so the template literal contains 'C:\\\\\\\\Users'."""
        scene = json.dumps({"panels": [], "width": 300, "height": 200, "path": "C:\\Users"})
        html = self._assemble(scene)
        # json.dumps("C:\Users") produces the string: C:\\Users (with 2 backslashes in repr).
        # The escaping then doubles each backslash, so the template literal has 4 literal backslashes.
        assert "C:\\\\\\\\Users" in html

    def test_embed_wasm_true_contains_init_object_syntax(self):
        """embed_wasm=True must use {module_or_path: wasmBytes} (not deprecated positional arg)."""
        scene = json.dumps({"panels": [], "width": 300, "height": 200})
        html = self._assemble(scene, embed_wasm=True)
        assert "module_or_path" in html, "WASM init must use { module_or_path: wasmBytes } syntax"

    def test_embed_wasm_false_no_b64(self):
        """embed_wasm=False must NOT contain base64-encoded WASM."""
        scene = json.dumps({"panels": [], "width": 300, "height": 200})
        html = self._assemble(scene, embed_wasm=False)
        assert "wasmB64" not in html
        assert "__wbg_init();" in html

    def test_empty_packed_data(self):
        """Empty packed_data must produce an empty packedB64 string in JS."""
        scene = json.dumps({"panels": [], "width": 300, "height": 200})
        html = self._assemble(scene, packed_data=b"")
        assert "createStandaloneAdapter('')" in html or "createStandaloneAdapter(''" in html

    def test_nonempty_packed_data_produces_b64(self):
        """Non-empty packed_data must produce a non-empty base64 string."""
        import base64

        data = b"\x00\x01\x02\x03\xff"
        scene = json.dumps({"panels": [], "width": 300, "height": 200})
        html = self._assemble(scene, packed_data=data)
        expected_b64 = base64.b64encode(data).decode("ascii")
        assert expected_b64 in html

    def test_html_contains_all_required_components(self):
        """The assembled HTML must contain: DOCTYPE, module script, WASM init,
        createStandaloneAdapter, _render call, and error handler."""
        scene = json.dumps({"panels": [], "width": 300, "height": 200})
        html = self._assemble(scene)
        assert "<!DOCTYPE html>" in html
        assert '<script type="module">' in html
        assert "__wbg_init" in html
        assert "createStandaloneAdapter" in html
        assert "_render(" in html or "await _render(" in html
        assert "main().catch" in html
        assert "Render error" in html

    def test_title_in_html(self):
        """Custom title must appear in the <title> tag."""
        scene = json.dumps({"panels": [], "width": 300, "height": 200})
        html = self._assemble(scene, title="My Chart")
        assert "<title>My Chart</title>" in html

    def test_no_double_escaping(self):
        """Scene JSON with normal content must not be double-escaped.
        The string 'hello world' should appear verbatim in the template literal."""
        scene = json.dumps({"panels": [], "width": 300, "height": 200, "text": "hello world"})
        html = self._assemble(scene)
        assert "hello world" in html


