class TestExtractInteractionConfig:
    """Edge cases for interaction config extraction from scene JSON."""

    def test_valid_scene_with_selections(self):
        from ferrum._html import _extract_interaction_config

        scene = json.dumps(
            {
                "interaction": {"zoom_enabled": True},
                "selections": [{"name": "sel1", "type": "point"}],
            }
        )
        result = json.loads(_extract_interaction_config(scene))
        assert result["zoom_enabled"] is True
        assert len(result["selections"]) == 1
        assert result["selections"][0]["name"] == "sel1"

    def test_scene_with_no_interaction_key(self):
        """Missing 'interaction' key should produce an empty config with selections."""
        from ferrum._html import _extract_interaction_config

        scene = json.dumps({"panels": [], "selections": [{"name": "s"}]})
        result = json.loads(_extract_interaction_config(scene))
        assert result["selections"] == [{"name": "s"}]

    def test_scene_with_no_selections_key(self):
        """Missing 'selections' key should produce empty selections list."""
        from ferrum._html import _extract_interaction_config

        scene = json.dumps({"interaction": {"zoom_enabled": True}})
        result = json.loads(_extract_interaction_config(scene))
        assert result["selections"] == []
        assert result["zoom_enabled"] is True

    def test_malformed_json_returns_empty(self):
        """Malformed JSON must not crash -- should return '{}'."""
        from ferrum._html import _extract_interaction_config

        result = _extract_interaction_config("not valid json {{{")
        assert result == "{}"

    def test_empty_string_returns_empty(self):
        from ferrum._html import _extract_interaction_config

        result = _extract_interaction_config("")
        assert result == "{}"


