class TestExtractBackgroundCss:
    """Edge cases for background CSS extraction."""

    def test_no_background_key(self):
        from ferrum._html import _extract_background_css

        scene = json.dumps({"panels": []})
        assert _extract_background_css(scene) == "#ffffff"

    def test_valid_background(self):
        from ferrum._html import _extract_background_css

        scene = json.dumps({"background": {"r": 255, "g": 0, "b": 0, "a": 255}})
        result = _extract_background_css(scene)
        assert "rgba(255,0,0,1.0)" == result

    def test_background_with_alpha(self):
        from ferrum._html import _extract_background_css

        scene = json.dumps({"background": {"r": 0, "g": 128, "b": 255, "a": 128}})
        result = _extract_background_css(scene)
        # a=128 -> 128/255 ~ 0.502
        assert "rgba(0,128,255," in result
        alpha = float(result.split(",")[3].rstrip(")"))
        assert abs(alpha - 128 / 255.0) < 0.01

    def test_background_missing_a_key_from_dict(
        self,
    ):  # BUG: KeyError on bg['a'] in _background_css_from_dict when alpha key absent
        """_background_css_from_dict should handle a background dict missing
        the 'a' (alpha) key without crashing.  The function uses bg['a']
        without .get() -- assemble_html calls this directly and would crash
        if a background dict lacked the alpha channel."""
        from ferrum._html import _background_css_from_dict

        try:
            result = _background_css_from_dict({"background": {"r": 100, "g": 100, "b": 100}})
        except KeyError:
            pytest.fail(
                "_background_css_from_dict raises KeyError when background dict "
                "is missing 'a' key -- bg['a'] should use .get('a', 255)"
            )

    def test_background_missing_a_key_wrapper(self):
        """_extract_background_css (wrapper) should not crash on missing 'a' key.
        With _background_css_from_dict now using .get('a', 255), the wrapper
        returns the correct rgba value instead of falling back to #ffffff."""
        from ferrum._html import _extract_background_css

        scene = json.dumps({"background": {"r": 100, "g": 100, "b": 100}})
        result = _extract_background_css(scene)
        assert result == "rgba(100,100,100,1.0)"

    def test_malformed_json_returns_default(self):
        from ferrum._html import _extract_background_css

        result = _extract_background_css("not json")
        assert result == "#ffffff"

    def test_null_background_returns_default(self):
        from ferrum._html import _extract_background_css

        scene = json.dumps({"background": None})
        result = _extract_background_css(scene)
        assert result == "#ffffff"


