# ---------------------------------------------------------------------------
# 10. HTML interaction config escaping in assembled HTML
# ---------------------------------------------------------------------------


class TestInteractionConfigEscaping:
    """Verify interaction config is properly escaped when embedded in HTML."""

    def test_single_quotes_in_interaction_config_escaped(self):
        """If interaction config contains single quotes, they must be escaped
        since the HTML embeds it in a JS single-quoted string."""
        from ferrum._html import assemble_html

        # Craft a scene with interaction data that includes a single quote
        scene = json.dumps(
            {
                "panels": [],
                "width": 300,
                "height": 200,
                "interaction": {"note": "it's a test"},
                "selections": [],
            }
        )
        html = assemble_html(scene)
        # The adapter call is the last occurrence of createStandaloneAdapter(
        # The interaction config is embedded in a JS single-quoted string
        # so single quotes inside must be escaped
        assert "it\\'s a test" in html

    def test_backslashes_in_interaction_config_escaped(self):
        """Backslashes in interaction config must be double-escaped."""
        from ferrum._html import assemble_html

        scene = json.dumps(
            {
                "panels": [],
                "width": 300,
                "height": 200,
                "interaction": {"path": "C:\\path"},
                "selections": [],
            }
        )
        html = assemble_html(scene)
        # The interaction config is extracted and JSON-serialized, then the
        # result is escaped for embedding in a JS single-quoted string.
        # Find the actual adapter invocation (the last createStandaloneAdapter call).
        import re

        calls = list(re.finditer(r"createStandaloneAdapter\('", html))
        assert len(calls) >= 1, "must have at least one createStandaloneAdapter call"
        last_call_start = calls[-1].start()
        adapter_region = html[last_call_start : last_call_start + 500]
        # The backslash must be double-escaped (C:\\\\path in the JS string)
        assert "\\\\" in adapter_region
